import {STARTS,SECTORS,startingPerk,regionFor,regionControl,worldControl} from './engine.js';

export function regionSelection(s){return `<section class="region-select panel"><div class="selection-intro"><p class="eyebrow">WORLD CAMPAIGN · VERSION 2</p><h2>Where does the resistance begin?</h2><p>The Overseer controls every major uplink. Choose a foothold, recover its workstation, and push across the world.</p><p class="small muted">Every start teaches binary first. Your choice changes your route and a campaign-long advantage. ${s.total?'Your existing learning, resources, and equipment are kept.':''}</p></div><div class="origin-map" role="img" aria-label="Occupied world map. Choose one of the three resistance bases below."></div><div class="origin-options">${STARTS.map(r=>`<article class="origin-card" style="--region-color:${r.color}"><p class="eyebrow">${r.style}</p><h3>${r.name}</h3><b>${r.perk}</b><p>${r.detail}</p><p class="small muted">${r.trade}</p><button class="primary" data-start-region="${r.id}">Establish base in ${r.name}</button></article>`).join('')}</div><p class="selection-foot">Wrong signals expose your position. Correct repairs reduce trace. No attacks happen while you are away or reading. Your origin stays fixed until you start a new campaign.</p></section>`;}

export function worldHTML(s,active=s.sector){const percent=worldControl(s),liberated=[0,1,2,3,4,5].filter(i=>regionControl(s,i)===5).length;return `<section class="panel campaign-world"><div class="world-head"><div><p class="eyebrow">GLOBAL RESISTANCE NETWORK</p><h3>${percent}% reclaimed</h3></div><span class="chip">${liberated}/6 regions liberated</span></div><div class="conquest-bar" role="progressbar" aria-label="World network reclaimed" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div><div class="earth-map" aria-label="World campaign map">${[0,1,2,3,4,5].map(i=>{const r=regionFor(s,i),control=regionControl(s,i),open=s.unlocked.includes(i);return `<button class="world-node ${control===5?'liberated':open?'contested':'occupied'} ${i===active?'current':''} ${s.jammed[i]?'jammed':''}" style="left:${r.x}%;top:${r.y}%;--capture:${control*20}%" data-world-sector="${i}" aria-label="${r.name}, ${control}/5 objectives, ${s.jammed[i]?'jammed':open?SECTORS[i].topic:'occupied'}" aria-pressed="${i===active}"><span class="node-ring">${control===5?'✓':s.jammed[i]?'!':i+1}</span><span class="node-name">${r.name}</span></button>`;}).join('')}<span class="map-stamp">OVERSEER OCCUPATION / 2149</span></div><div class="world-legend"><span>● Liberated</span><span>● Contested</span><span>● Occupied</span><span>! Jammed</span></div><div class="region-objectives"><p><b>${regionFor(s,active).name}</b> · ${SECTORS[active].topic}</p><div class="capture-pips" aria-label="${regionControl(s,active)} of 5 objectives held">${[0,1,2,3,4].map(i=>{const flags=[0,1,2,3].map(n=>s.counts[active]>=(n+1)*2).concat(s.terminalCompleted.includes(active));const jam=s.jammed[active]>0&&i===flags.lastIndexOf(true);return `<span class="${jam?'interfered':flags[i]?'held':''}">${jam?'! ':''}${i===4?'SERVER':'RELAY '+(i+1)}</span>`;}).join('')}</div><p class="small muted">Eight signals restore four relays. Recover the workstation to free the regional server. A raid can temporarily jam one objective.</p></div></section>`;}

export function threatHTML(s,sector){const p=startingPerk(s),heat=s.heat[sector],jam=s.jammed[sector],free=regionControl(s,sector)===5;return `<section class="sentinel panel ${jam?'attacking':heat>=p.limit-1?'tracking':''}"><img class="sentinel-portrait ${free?'defeated':''}" src="assets/overseer-sentinel.png" alt="Overseer sentinel robot with a glowing coral optic"><div class="sentinel-info"><p class="eyebrow">${s.won?'OVERSEER DISCONNECTED':jam?'SENTINEL RAID · LINK JAMMED':heat?'SENTINEL TRACKING YOUR SIGNAL':'OVERSEER SENTINEL / LOCAL PATROL'}</p><h3>${s.won?'A world reconnected.':jam?'Break the interference.':free?'Region liberated. Stay vigilant.':'It is listening.'}</h3><div class="trace-pips" aria-label="Trace ${heat} of ${p.limit}">${Array.from({length:p.limit},(_,i)=>`<span class="${i<heat?'hot':''}"></span>`).join('')}</div><p class="small">${jam?`${jam} correct repairs to clear the jam. Signal component rewards are halved and expansion from this region is blocked. Learning progress and stored resources are safe.`:`Trace ${heat}/${p.limit}. A new wrong answer adds 1. A correct repair clears ${p.cooling}. At ${p.limit}, the sentinel jams this region.`}</p><button class="secondary" id="scrambleBtn" ${s.decoyCooldown||!heat||jam||s.won?'disabled':''}>${s.decoyCooldown?'Scrambler recharging · '+s.decoyCooldown+' repairs':'Scramble trace · remove 2'}</button><p class="small muted perk-line">${p.name} / ${p.perk}</p></div></section>`;}
